SELECT jsonb_build_object('rows',count(*),'exact_target',coalesce(bool_and(id='bf01dab5-2588-5135-846f-b546bb6d98a3'::uuid AND user_id='00e9603c-2f57-5978-8df5-fbff48cddc0d'::uuid),false),'revision_zero',coalesce(bool_and(revision=0 AND privacy_generation=0),false),'original_fields',coalesce(bool_and(status='active' AND display_name IS NULL AND avatar_media_id IS NULL AND city IS NULL AND state IS NULL AND country IS NULL AND archived_at IS NULL),false)) FROM app.customer_profiles WHERE id='bf01dab5-2588-5135-846f-b546bb6d98a3'::uuid;
